shellCommands.command:
(npx vite preview --port 4173 --strictPort > /tmp/preview.log 2>&1 &) ; mkdir -p /tmp/pwscripts && cat > /tmp/pwscripts/check.mjs <<'EOF'
import { chromium } from '/tmp/pw/node_modules/playwright/index.mjs';
const url = process.argv[2];
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1200, height: 1000 } });
const errors = [];
page.on('pageerror', e => errors.push('pageerror: ' + e.message));
page.on('console', m => { if (m.type() === 'error' || m.type()==='warning') errors.push(m.type()+': ' + m.text()); });
await page.goto(url);
await page.waitForSelector('.cm-content', { timeout: 15000 });
await page.screenshot({ path: '/tmp/pwscripts/1-empty.png', fullPage: true });
// submit empty -> errors
await page.click('button[type=submit]');
await page.screenshot({ path: '/tmp/pwscripts/2-errors.png', fullPage: true });
await page.fill('input', 'Мой заголовок');
await page.click('.cm-content');
await page.keyboard.type('# Привет\n\nЭто **жирный**, _курсив_ и ~~зачёркнутый~~ текст.\n\n- пункт 1\n- пункт 2\n\n[ссылка](https://example.com) `код`\n\n<script>alert(1)</script><img src=x onerror=alert(2)>\n\n{{ var }}');
await page.waitForTimeout(300);
const previewHtml = await page.$eval('.yfm', el => el.innerHTML);
console.log('PREVIEW:', previewHtml);
await page.screenshot({ path: '/tmp/pwscripts/3-typed.png', fullPage: true });
await page.click('button[type=submit]');
await page.waitForTimeout(300);
console.log('AFTER SUBMIT editor text:', JSON.stringify(await page.$eval('.cm-content', el => el.innerText)));
console.log('CARD:', await page.$eval('.g-card', el => el.innerText));
await page.screenshot({ path: '/tmp/pwscripts/4-submitted.png', fullPage: true });
console.log('ERRORS:', errors);
await browser.close();
EOF
sleep 2; node /tmp/pwscripts/check.mjs http://localhost:4173/

cat > /tmp/pwscripts/errs.mjs <<'EOF'
import { chromium } from '/tmp/pw/node_modules/playwright/index.mjs';
const browser = await chromium.launch();
const page = await browser.newPage();
